import React,{useEffect,useMemo,useRef,useState} from 'react';
import {KeyRound,Activity,AlertCircle,ArrowRight,ArrowUpRight, Bell,CalendarDays,Check,CheckCircle2,Clock,Compass, CreditCard, DollarSign, Eye, Filter, Heart, LogOut, MapPin, Menu, MessageSquare, Plus, Search, ShieldCheck, Star, TrendingUp, Users, Wallet, X, Building2, ClipboardList, LayoutDashboard, RefreshCw, Ban, Pencil, Trash2, FileText, Tag, Send, Trophy, Sparkles} from 'lucide-react';
import api from './services/api';

const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(n||0));
const parseLocalDate=v=>{if(!v)return null;const s=String(v);if(/^\d{4}-\d{2}-\d{2}$/.test(s)){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d);}return new Date(s);};
const dateText=v=>{const d=parseLocalDate(v);return d&&!Number.isNaN(d.getTime())?d.toLocaleDateString('vi-VN'):'';};
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const statusText={PENDING_OWNER:'Chờ chủ sân',CONFIRMED:'Đã xác nhận',REJECTED:'Bị từ chối',CANCELLED:'Đã hủy',COMPLETED:'Hoàn thành',PENDING:'Chờ duyệt',PAID:'Đã thanh toán',REFUND_PENDING:'Chờ hoàn tiền',REFUNDED:'Đã hoàn tiền',ACTIVE:'Đang hoạt động',LOCKED:'Đã khóa',DELETED:'Đã vô hiệu hóa',ARCHIVED:'Đã lưu trữ',VISIBLE:'Đang hiển thị',HIDDEN:'Đã ẩn',PENDING_VENUE:'Chờ duyệt'};
const menuByRole={PLAYER:[['Tổng quan','dashboard',LayoutDashboard],['Tìm sân','venues',Compass],['Lịch đặt của tôi','bookings',CalendarDays],['Sân yêu thích','favorites',Heart],['Thanh toán','payments',Wallet],['Thông báo','notifications',Bell]],OWNER:[['Tổng quan','dashboard',LayoutDashboard],['Quản lý sân bóng','venues',Building2],['Lịch đặt sân','bookings',CalendarDays],['Doanh thu','revenue',TrendingUp],['Đánh giá','ownerReviews',MessageSquare],['Thông báo','notifications',Bell]],ADMIN:[['Tổng quan','dashboard',LayoutDashboard],['Quản lý người dùng','accounts',Users],['Quản lý sân bóng','venues',Building2],['Đặt sân','bookings',CalendarDays],['Thanh toán','payments',CreditCard],['Đánh giá','reviews',MessageSquare],['Danh mục','categories',Tag],['Thông báo','notifications',Bell],['Nhật ký hệ thống','audit',FileText]]};
const dayLabels=['','Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','Chủ nhật'];

function App(){
 const [user,setUser]=useState(()=>{try{return JSON.parse(localStorage.getItem('snm_user'))}catch{return null}});
 const [token,setToken]=useState(localStorage.getItem('snm_token'));
 const [page,setPage]=useState('dashboard'); const [venues,setVenues]=useState([]); const [rows,setRows]=useState([]); const [stats,setStats]=useState({}); const [categories,setCategories]=useState([]); const [owners,setOwners]=useState([]);
 const [favoriteIds,setFavoriteIds]=useState(()=>new Set());
 const [venuePage,setVenuePage]=useState(0); const [venuePageInfo,setVenuePageInfo]=useState({totalPages:0,totalElements:0}); const [venueCategory,setVenueCategory]=useState(''); const [busy,setBusy]=useState(false); const [saving,setSaving]=useState(false); const [authError,setAuthError]=useState(''); const [scheduleModal,setScheduleModal]=useState(null); const [detailModal,setDetailModal]=useState(null); const [notice,setNotice]=useState(''); const [error,setError]=useState(''); const [search,setSearch]=useState(''); const [debouncedSearch,setDebouncedSearch]=useState(''); const [modal,setModal]=useState(null); const [mobileMenu,setMobileMenu]=useState(false);
 const toastTimer=useRef(null);
 const role=user?.role;

 const toast=(m,bad=false)=>{if(toastTimer.current)clearTimeout(toastTimer.current);setNotice(bad?'':m);setError(bad?m:'');toastTimer.current=setTimeout(()=>{setNotice('');setError('')},3500)};
 const goPage=next=>{if(next!==page){setRows([]);if(next==='venues')setVenuePage(0);setPage(next)}setMobileMenu(false)};
 const logout=()=>{localStorage.removeItem('snm_token');localStorage.removeItem('snm_user');setToken(null);setUser(null);setRows([]);setVenues([]);setOwners([]);setFavoriteIds(new Set());setModal(null);setDetailModal(null);setScheduleModal(null);setPage('dashboard')};

 useEffect(()=>{
   const onUnauthorized=()=>{setToken(null);setUser(null);setRows([]);setVenues([]);setOwners([]);setFavoriteIds(new Set());setModal(null);setDetailModal(null);setScheduleModal(null);setPage('dashboard');setAuthError('Phiên đăng nhập đã hết hạn hoặc tài khoản đã bị khóa. Vui lòng đăng nhập lại.')};
   window.addEventListener('snm:unauthorized',onUnauthorized);
   return()=>{window.removeEventListener('snm:unauthorized',onUnauthorized);if(toastTimer.current)clearTimeout(toastTimer.current)};
 },[]);

 useEffect(()=>{
   const t=setTimeout(()=>{setDebouncedSearch(search);setVenuePage(0)},350);
   return()=>clearTimeout(t);
 },[search]);

 const auth=async (path,formData)=>{setBusy(true);setAuthError('');try{const r=await api.post(`/auth/${path}`,formData);localStorage.setItem('snm_token',r.data.token);localStorage.setItem('snm_user',JSON.stringify(r.data.user));setToken(r.data.token);setUser(r.data.user);setModal(null);setPage('dashboard');toast(path==='register'?'Đăng ký thành công':'Đăng nhập thành công')}catch(e){setAuthError(e.response?.data?.message||'Không thể xác thực tài khoản')}finally{setBusy(false)}};

 const load=async()=>{if(!user)return;setBusy(true);try{
   const [cat]=await Promise.all([api.get('/categories')]);setCategories(cat.data);
   if(role==='PLAYER'){
     if(page==='dashboard'){const [d,v,fav]=await Promise.all([api.get('/player/dashboard'),api.get('/venues'),api.get('/favorites')]);setStats(d.data);setVenues(v.data);setFavoriteIds(new Set((fav.data||[]).map(x=>x.id)))}
     else if(page==='venues'){const [r,fav]=await Promise.all([api.get('/venues/page',{params:{q:debouncedSearch,categoryId:venueCategory||undefined,page:venuePage,size:9}}),api.get('/favorites')]);setVenues(r.data.content||[]);setVenuePageInfo(r.data);setFavoriteIds(new Set((fav.data||[]).map(x=>x.id)))}
     else if(page==='bookings')setRows((await api.get('/bookings/mine')).data);
     else if(page==='favorites'){const fav=(await api.get('/favorites')).data||[];setRows(fav);setFavoriteIds(new Set(fav.map(x=>x.id)))}
     else if(page==='payments')setRows((await api.get('/payments/mine')).data);
     else if(page==='notifications')setRows((await api.get('/notifications')).data);
   } else if(role==='OWNER'){
     if(page==='dashboard'){const [d,v,b]=await Promise.all([api.get('/owner/dashboard'),api.get('/owner/venues'),api.get('/owner/bookings')]);setStats(d.data);setVenues(v.data);setRows(b.data)}
     else if(page==='venues')setRows((await api.get('/owner/venues')).data);
     else if(page==='bookings')setRows((await api.get('/owner/bookings')).data);
     else if(page==='revenue'){const [p,r]=await Promise.all([api.get('/owner/revenue'),api.get('/owner/dashboard')]);setRows(p.data);setStats(r.data)}
     else if(page==='ownerReviews')setRows((await api.get('/owner/reviews')).data);
     else if(page==='notifications')setRows((await api.get('/notifications')).data);
   } else if(role==='ADMIN'){
     if(page==='dashboard'){const [d,v,b]=await Promise.all([api.get('/admin/dashboard'),api.get('/admin/venues'),api.get('/admin/bookings')]);setStats(d.data);setVenues(v.data);setRows(b.data)}
     else if(page==='venues'){const [v,acc]=await Promise.all([api.get('/admin/venues'),api.get('/admin/accounts')]);setRows(v.data);setOwners((acc.data||[]).filter(a=>a.status==='ACTIVE'&&(a.role==='OWNER'||a.role==='ADMIN')))}
     else {const endpoint={accounts:'/admin/accounts',bookings:'/admin/bookings',payments:'/admin/payments',reviews:'/admin/reviews',categories:'/admin/categories',audit:'/admin/audit-logs',notifications:'/notifications'}[page];if(endpoint)setRows((await api.get(endpoint)).data)}
   }
 }catch(e){if(e.response?.status!==401)toast(e.response?.data?.message||'Không tải được dữ liệu. Hãy kiểm tra API và quyền tài khoản.',true)}finally{setBusy(false)}};

 useEffect(()=>{load()},[user,page,venuePage,venueCategory,debouncedSearch]);

 const refresh=()=>load();

 const toggleFavorite=async venue=>{
   try{
     const r=await api.post(`/favorites/${venue.id}`);
     const added=!!r.data?.favorite;
     setFavoriteIds(prev=>{const next=new Set(prev);if(added)next.add(venue.id);else next.delete(venue.id);return next});
     toast(added?'Đã lưu sân vào danh sách yêu thích':'Đã bỏ lưu sân yêu thích');
     if(page==='favorites'||page==='dashboard')await load();
   }catch(e){
     toast(e.response?.data?.message||'Không thể cập nhật sân yêu thích',true);
   }
 };

 const filteredFavorites=useMemo(()=>{
   if(page!=='favorites')return [];
   const q=search.trim().toLowerCase();
   return rows.filter(v=>{
     const matchCat=!venueCategory||String(v.category_id)===String(venueCategory);
     const matchText=!q||`${v.name||''} ${v.address||''} ${v.district||''}`.toLowerCase().includes(q);
     return matchCat&&matchText;
   });
 },[page,rows,search,venueCategory]);

 const openDetail=async(kind,id)=>{
   try{
     const url=kind==='account'?`/admin/accounts/${id}`:kind==='adminVenue'?`/admin/venues/${id}`:`/owner/venues/${id}`;
     const r=await api.get(url);
     setDetailModal({kind,data:r.data});
   }catch(e){
     toast(e.response?.data?.message||'Không tải được thông tin chi tiết',true);
   }
 };

 const openSchedule=async venue=>{try{const r=await api.get(`/owner/venues/${venue.id}/schedules`);const defaults=Array.from({length:7},(_,i)=>({dayOfWeek:i+1,openTime:'06:00',closeTime:'22:00',slotMinutes:60,isClosed:false}));const existing=r.data||[];setScheduleModal({venue,rows:defaults.map(d=>{const found=existing.find(x=>Number(x.day_of_week)===d.dayOfWeek);return found?{...d,openTime:String(found.open_time).slice(0,5),closeTime:String(found.close_time).slice(0,5),slotMinutes:found.slot_minutes,isClosed:!!found.is_closed}:d})});}catch(e){toast('Không tải được lịch hoạt động',true)}};
 const saveSchedules=async scheduleRows=>{
   const bad=scheduleRows.find(r=>!r.isClosed&&(!r.openTime||!r.closeTime||r.closeTime<=r.openTime));
   if(bad){toast('Giờ đóng cửa phải lớn hơn giờ mở cửa cho các ngày mở cửa',true);return}
   try{await api.put(`/owner/venues/${scheduleModal.venue.id}/schedules`,scheduleRows);setScheduleModal(null);toast('Đã lưu lịch hoạt động')}catch(e){toast(e.response?.data?.message||'Không thể lưu lịch hoạt động',true)}
 };

 const act=async(method,url,data,successMsg='Đã cập nhật thành công')=>{setSaving(true);try{const res=await api[method](url,data);if(res?.data?.id&&res?.data?.status){setRows(prev=>prev.map(r=>Number(r.id)===Number(res.data.id)?{...r,status:res.data.status}:r))}toast(successMsg);setModal(null);await load();return true}catch(e){const payload=e.response?.data;const detail=payload?.message||payload?.error||payload?.detail||e.message||'Không xác định được nguyên nhân';toast(`Không thể lưu (${e.response?.status||'mất kết nối'}): ${detail}`,true);return false}finally{setSaving(false)}};

 const openForm=(kind,item=null)=>{
   const footballCat=categories.find(c=>String(c.name||'').toLowerCase().includes('bóng đá'))||categories[0];
   const defaultCat=footballCat?.id??'';
   const defaultOwner=owners[0]?.id??'';
   let form=item?{...item}:{};
   if(kind==='venue')form=item?{...item,categoryId:item.category_id??defaultCat,pricePerHour:item.price_per_hour,imageUrl:item.image_url}:{categoryId:defaultCat,city:'Hà Nội'};
   else if(kind==='adminVenue')form=item?{...item,ownerId:item.owner_id??defaultOwner,categoryId:item.category_id??defaultCat,pricePerHour:item.price_per_hour,imageUrl:item.image_url,status:item.status||'ACTIVE'}:{ownerId:defaultOwner,categoryId:defaultCat,city:'Hà Nội',status:'ACTIVE'};
   else if(kind==='account')form=item?{...item,fullName:item.full_name,status:item.status||'ACTIVE'}:{role:'PLAYER'};
   else if(kind==='resetPassword')form={password:'',fullName:item?.full_name||'',email:item?.email||''};
   else if(kind==='booking')form={playDate:localToday(),startTime:'18:00',hours:1,...(item||{})};
   else if(kind==='payment')form={method:'BANK_TRANSFER',...(item||{})};
   else if(kind==='review')form={rating:5,...(item||{})};
   else if(kind==='broadcast')form={target:'ALL'};
   setModal({kind,item,form});
 };

 const setField=(k,v)=>setModal(m=>({...m,form:{...m.form,[k]:v}}));
 const submitModal=async e=>{e.preventDefault();const f=modal.form||{};switch(modal.kind){
   case 'venue': return modal.item?act('put',`/owner/venues/${modal.item.id}`,f,'Đã cập nhật sân bóng'):act('post','/owner/venues',f,'Đã tạo sân bóng mới (chờ duyệt)');
   case 'adminVenue': return modal.item?act('put',`/admin/venues/${modal.item.id}`,f,'Đã cập nhật thông tin sân'):act('post','/admin/venues',f,'Đã thêm sân bóng mới');
   case 'account': return modal.item?act('put',`/admin/accounts/${modal.item.id}`,f,'Đã cập nhật tài khoản'):act('post','/admin/accounts',f,'Đã tạo người dùng mới');
   case 'resetPassword': return act('patch',`/admin/accounts/${modal.item.id}/password`,{password:f.password},'Đã đặt lại mật khẩu thành công');
   case 'category': return modal.item?act('put',`/admin/categories/${modal.item.id}`,f):act('post','/admin/categories',f);
   case 'booking': return act('post','/bookings',{...f,hours:Number(f.hours||1)},'Đã gửi yêu cầu đặt sân');
   case 'payment': return act('post','/payments',f,'Đã gửi thông tin thanh toán');
   case 'review': return act('post','/reviews',{...f,rating:Number(f.rating||5)},'Đã gửi đánh giá');
   case 'broadcast': return act('post','/admin/notifications',f,'Đã gửi thông báo');
   default:return;
 }};

 if(!user)return <AuthScreen onAuth={auth} busy={busy} authError={authError} clearAuthError={()=>setAuthError('')}/>;
 const menu=menuByRole[role]||menuByRole.PLAYER;
 return <div className="app-shell">
   <aside className={`sidebar ${mobileMenu?'show':''}`}><div className="brand"><div className="brand-mark"><Trophy size={21}/></div><div><b>Sân Nhà Mình</b><small>SPORTS BOOKING</small></div><button className="icon-btn close-mobile" onClick={()=>setMobileMenu(false)}><X/></button></div>
    <div className="workspace-label">KHÔNG GIAN LÀM VIỆC</div><div className="side-nav">{menu.map(([label,key,Icon])=><button key={key} className={`nav-item ${page===key?'active':''}`} onClick={()=>goPage(key)}><Icon size={18}/><span>{label}</span>{key==='notifications'&&<i className="nav-dot"/>}</button>)}</div>
    <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><Sparkles size={18}/></div><b>Cần hỗ trợ?</b><p>Đội ngũ Sân Nhà Mình luôn sẵn sàng giúp bạn.</p><a href="mailto:support@sannhaminh.vn">Liên hệ hỗ trợ <ArrowRight size={13}/></a></div><div className="profile-mini"><div className="avatar">{user.fullName?.charAt(0)||'U'}</div><div className="profile-info"><b>{user.fullName}</b><small>{roleLabel(role)}</small></div><button className="icon-btn" title="Đăng xuất" onClick={logout}><LogOut size={17}/></button></div></div>
   </aside>
   <main className="main-area"><header className="topbar"><div className="top-left"><button className="icon-btn mobile-menu" onClick={()=>setMobileMenu(true)}><Menu/></button><div className="crumb">Workspace <span>/</span> <b>{menu.find(x=>x[1]===page)?.[0]||'Tổng quan'}</b></div></div><div className="top-actions"><div className="today-pill"><CalendarDays size={15}/>{new Date().toLocaleDateString('vi-VN',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'})}</div><button className="icon-btn notification-btn" onClick={()=>goPage('notifications')}><Bell size={18}/><i/></button><div className="top-avatar">{user.fullName?.charAt(0)||'U'}</div></div></header>
    <div className="page-content"><div className="page-heading"><div><div className="eyebrow">{roleLabel(role)} / SÂN NHÀ MÌNH</div><h1>{pageTitle(page,role)}</h1><p>{pageSubtitle(page,role)}</p></div><div className="heading-actions"><button className="btn btn-light" onClick={refresh}><RefreshCw size={16}/> Làm mới</button>{(page==='venues'&&(role==='OWNER'||role==='ADMIN')||page==='accounts'&&role==='ADMIN'||page==='categories'&&role==='ADMIN')&&<button className="btn btn-primary" onClick={()=>openForm(page==='venues'?(role==='ADMIN'?'adminVenue':'venue'):page==='accounts'?'account':'category')}><Plus size={17}/> {page==='accounts'?'Thêm người dùng':page==='venues'?'Thêm sân bóng':'Thêm mới'}</button>}{page==='notifications'&&role==='ADMIN'&&<button className="btn btn-primary" onClick={()=>openForm('broadcast')}><Send size={16}/> Tạo thông báo</button>}</div></div>
    {notice&&<div className="toast success"><CheckCircle2 size={17}/>{notice}</div>}{error&&<div className="toast danger"><AlertCircle size={17}/>{error}</div>}
    {busy&&<div className="loading-line"><span/></div>}
    {page==='dashboard'&&<Dashboard role={role} stats={stats} venues={venues} rows={rows} setPage={goPage} openForm={openForm} openDetail={openDetail} openSchedule={openSchedule} act={act} saving={saving} favoriteIds={favoriteIds} onToggleFavorite={role==='PLAYER'?toggleFavorite:null}/>}
    {page==='venues'&&role==='PLAYER'&&<VenueExplorer venues={venues} search={search} setSearch={setSearch} categories={categories} category={venueCategory} setCategory={setVenueCategory} pageInfo={venuePageInfo} page={venuePage} setPage={setVenuePage} openBooking={v=>openForm('booking',{venueId:v.id,venueName:v.name,hours:1})} favoriteIds={favoriteIds} onToggleFavorite={toggleFavorite}/>}
    {page==='venues'&&role==='OWNER'&&<OwnerVenues rows={rows} categories={categories} openForm={openForm} openDetail={id=>openDetail('ownerVenue',id)} openSchedule={openSchedule} act={act}/>}
    {page==='venues'&&role==='ADMIN'&&<AdminVenues rows={rows} categories={categories} act={act} openForm={openForm} openDetail={id=>openDetail('adminVenue',id)}/>}
    {page==='bookings'&&role==='PLAYER'&&<PlayerBookings rows={rows} act={act} openForm={openForm}/>}
    {page==='bookings'&&role==='OWNER'&&<OwnerBookings rows={rows} act={act} saving={saving}/>}
    {page==='bookings'&&role==='ADMIN'&&<AdminBookings rows={rows} act={act}/>}
    {page==='favorites'&&<VenueExplorer venues={filteredFavorites} search={search} setSearch={setSearch} categories={categories} category={venueCategory} setCategory={setVenueCategory} pageInfo={{totalElements:filteredFavorites.length,totalPages:filteredFavorites.length?1:0}} page={0} setPage={()=>{}} openBooking={v=>openForm('booking',{venueId:v.id,venueName:v.name,hours:1})} favoriteIds={favoriteIds} onToggleFavorite={toggleFavorite}/>}
    {page==='payments'&&role==='PLAYER'&&<PlayerPayments rows={rows} openForm={openForm}/>}
    {page==='payments'&&role==='ADMIN'&&<AdminPayments rows={rows} act={act}/>}
    {page==='revenue'&&<Revenue rows={rows} stats={stats}/>}{page==='ownerReviews'&&<OwnerReviews rows={rows} act={act}/>}
    {page==='accounts'&&<AdminAccounts rows={rows} openForm={openForm} openDetail={id=>openDetail('account',id)} act={act}/>}
    {page==='reviews'&&<AdminReviews rows={rows} act={act}/>}
    {page==='categories'&&<Categories rows={rows} openForm={openForm} act={act}/>}
    {page==='notifications'&&<Notifications rows={rows} act={act}/>}
    {page==='audit'&&<Audit rows={rows}/>}
    <footer className="footer">© 2026 Sân Nhà Mình <span>•</span> Kết nối đam mê, đặt sân dễ dàng</footer></div>
   </main>
   {modal&&<Modal modal={modal} setModal={setModal} setField={setField} submit={submitModal} busy={busy||saving} categories={categories} owners={owners}/>}
   {detailModal&&<DetailModal detail={detailModal} onClose={()=>setDetailModal(null)} onEdit={()=>{const {kind,data}=detailModal;setDetailModal(null);openForm(kind==='ownerVenue'?'venue':kind,data)}}/>}
   {scheduleModal&&<ScheduleModal value={scheduleModal} onClose={()=>setScheduleModal(null)} onSave={saveSchedules}/>}
 </div>
}
function roleLabel(r){return ({PLAYER:'Khách hàng',OWNER:'Chủ sân',ADMIN:'Quản trị viên'})[r]||'Thành viên'}
function pageTitle(p,r){return ({dashboard:'Tổng quan',venues:r==='PLAYER'?'Khám phá sân thể thao':r==='OWNER'?'Quản lý sân bóng của bạn':'Quản lý sân bóng',ownerReviews:'Đánh giá từ khách hàng',bookings:r==='OWNER'?'Quản lý lịch đặt':'Lịch đặt sân',favorites:'Sân yêu thích',payments:'Quản lý thanh toán',revenue:'Phân tích doanh thu',accounts:'Quản lý người dùng',reviews:'Kiểm duyệt đánh giá',categories:'Danh mục sân',notifications:'Thông báo',audit:'Nhật ký hoạt động'})[p]||'Tổng quan'}
function pageSubtitle(p,r){return ({dashboard:'Theo dõi hoạt động và những chỉ số quan trọng của bạn.',venues:'Thêm, xem chi tiết, chỉnh sửa và quản lý trạng thái sân bóng.',bookings:'Theo dõi, xác nhận và quản lý các lịch đặt sân.',payments:'Minh bạch giao dịch và trạng thái thanh toán.',accounts:'Thêm, xem chi tiết, chỉnh sửa, phân quyền và quản lý tài khoản người dùng.',reviews:'Đảm bảo nội dung đánh giá hữu ích và phù hợp.',categories:'Tổ chức các loại hình sân thể thao trên hệ thống.',notifications:'Cập nhật những thông tin mới nhất từ hệ thống.',audit:'Theo dõi các thao tác quản trị và lịch sử hệ thống.'})[p]||'Thông tin được cập nhật trực tiếp từ hệ thống.'}

function AuthScreen({onAuth,busy,authError,clearAuthError}){const [mode,setMode]=useState('login');const [form,setForm]=useState({email:'',password:'',role:'PLAYER'});const change=(k,v)=>setForm(f=>({...f,[k]:v}));const submit=e=>{e.preventDefault();onAuth(mode==='login'?'login':'register',form)};return <div className="auth-page"><div className="auth-visual"><div className="auth-brand"><div className="brand-mark"><Trophy/></div><b>Sân Nhà Mình</b></div><div className="auth-copy"><span className="pill-light"><Sparkles size={14}/> PLAY MORE. LIVE MORE.</span><h1>Sân chơi của bạn.<br/><em>Đam mê của chúng ta.</em></h1><p>Khám phá, kết nối và đặt sân thể thao yêu thích chỉ trong vài thao tác đơn giản.</p><div className="auth-stats"><div><b>500+</b><small>Sân thể thao</small></div><div><b>10K+</b><small>Lượt đặt sân</small></div><div><b>24/7</b><small>Đặt sân trực tuyến</small></div></div></div><div className="auth-image-caption">Tìm sân phù hợp · Đặt lịch linh hoạt · Trải nghiệm trọn vẹn</div></div><div className="auth-panel"><div className="auth-panel-inner"><div className="mobile-auth-brand"><div className="brand-mark"><Trophy/></div><b>Sân Nhà Mình</b></div><div className="auth-welcome"><span className="eyebrow">CHÀO MỪNG BẠN ĐẾN VỚI SÂN NHÀ MÌNH</span><h2>{mode==='login'?'Chào mừng trở lại!':'Tạo tài khoản mới'}</h2><p>{mode==='login'?'Đăng nhập để tiếp tục hành trình thể thao của bạn.':'Tham gia cộng đồng thể thao ngay hôm nay.'}</p></div>{authError&&<div className="toast danger"><AlertCircle size={16}/>{authError}</div>}<form onSubmit={submit} className="auth-form">{mode==='register'&&<><label>Họ và tên<input required value={form.fullName||''} onChange={e=>change('fullName',e.target.value)} placeholder="Nguyễn Văn A"/></label><label>Số điện thoại<input value={form.phone||''} onChange={e=>change('phone',e.target.value)} placeholder="09xx xxx xxx"/></label><label>Vai trò<select value={form.role||'PLAYER'} onChange={e=>change('role',e.target.value)}><option value="PLAYER">Tôi muốn đặt sân</option><option value="OWNER">Tôi là chủ sân</option></select></label></>}<label>Email<input type="email" required value={form.email} onChange={e=>change('email',e.target.value)} placeholder="name@example.com"/></label><label>Mật khẩu<input type="password" required minLength="8" value={form.password} onChange={e=>change('password',e.target.value)} placeholder="Tối thiểu 8 ký tự"/></label><button className="btn btn-primary btn-wide" disabled={busy}>{busy?'Đang xử lý...':mode==='login'?'Đăng nhập':'Tạo tài khoản'} <ArrowRight size={17}/></button></form><div className="auth-switch">{mode==='login'?'Chưa có tài khoản?':'Bạn đã có tài khoản?'} <button onClick={()=>{clearAuthError();setMode(mode==='login'?'register':'login');setForm({email:'',password:'',role:'PLAYER'})}}>{mode==='login'?'Đăng ký ngay':'Đăng nhập'}</button></div><div className="auth-terms">Bằng việc tiếp tục, bạn đồng ý với Điều khoản dịch vụ và Chính sách bảo mật của chúng tôi.</div></div></div></div>}

function StatCard({label,value,sub,Icon,trend}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><div className="stat-icon"><Icon size={19}/></div></div><strong>{value??'—'}</strong><div className="stat-bottom">{trend&&<span className="trend"><ArrowUpRight size={14}/>{trend}</span>}<small>{sub||'So với tổng quan hệ thống'}</small></div></div>}
function Dashboard({role,stats,venues,rows,setPage,openForm,openDetail,openSchedule,act,saving,favoriteIds,onToggleFavorite}){
 if(role==='PLAYER')return <><div className="welcome-banner"><div><span>THỨC DẬY VÀ VẬN ĐỘNG</span><h2>Sẵn sàng cho trận đấu tiếp theo?</h2><p>Khám phá sân gần bạn và lên lịch cho cuộc vui hôm nay.</p><button className="btn btn-white" onClick={()=>setPage('venues')}>Khám phá sân <ArrowRight size={16}/></button></div><div className="banner-ball">⚽</div></div><div className="stats-grid"><StatCard label="Tổng lịch đặt" value={stats.bookingCount||0} Icon={CalendarDays} sub="Tất cả lịch đặt của bạn"/><StatCard label="Sân yêu thích" value={stats.favoriteCount||0} Icon={Heart} sub="Địa điểm đã lưu"/><StatCard label="Lịch sắp tới" value={stats.upcoming?.length||0} Icon={Clock} sub="Đang chờ hoặc đã xác nhận"/></div><SectionHead title="Lịch đặt sắp tới" action="Xem tất cả" onAction={()=>setPage('bookings')}/><div className="booking-preview">{(stats.upcoming||[]).length?stats.upcoming.slice(0,4).map(b=>{const d=parseLocalDate(b.play_date);return <div className="preview-row" key={b.id}><div className="date-tile"><b>{d?d.getDate():'—'}</b><small>TH{d?d.getMonth()+1:''}</small></div><div className="preview-info"><b>{b.venue_name}</b><small><MapPin size={13}/>{b.address}</small><small><Clock size={13}/>{String(b.start_time||'').slice(0,5)} – {String(b.end_time||'').slice(0,5)}</small></div><Status value={b.status}/></div>}):<Empty text="Bạn chưa có lịch đặt nào. Hãy khám phá sân thể thao nhé!" action="Tìm sân ngay" onClick={()=>setPage('venues')}/>}</div><SectionHead title="Sân nổi bật" action="Khám phá tất cả" onAction={()=>setPage('venues')}/><VenueGrid venues={venues.slice(0,3)} book={v=>openForm('booking',{venueId:v.id,venueName:v.name,hours:1})} favoriteIds={favoriteIds} onToggleFavorite={onToggleFavorite}/></>;
 if(role==='OWNER')return <><div className="welcome-banner owner-banner"><div><span>KHÔNG GIAN CHỦ SÂN</span><h2>Quản lý sân. Phát triển đam mê.</h2><p>Theo dõi lịch đặt, doanh thu và chăm sóc khách hàng trên một nền tảng.</p><button className="btn btn-white" onClick={()=>openForm('venue')}>Thêm sân mới <Plus size={16}/></button></div><div className="banner-ball">🏟️</div></div><div className="stats-grid"><StatCard label="Sân đang quản lý" value={stats.venueCount||0} Icon={Building2}/><StatCard label="Yêu cầu chờ duyệt" value={stats.pendingCount||0} Icon={Clock}/><StatCard label="Doanh thu tháng" value={money(stats.monthRevenue)} Icon={Wallet}/></div><SectionHead title="Yêu cầu đặt sân mới" action="Quản lý lịch đặt" onAction={()=>setPage('bookings')}/><OwnerBookings rows={rows.filter(x=>String(x.status||'').trim().toUpperCase()==='PENDING_OWNER').slice(0,5)} act={act} saving={saving}/><SectionHead title="Sân của bạn" action="Xem tất cả" onAction={()=>setPage('venues')}/><OwnerVenues rows={venues.slice(0,4)} openForm={openForm} openDetail={id=>openDetail('ownerVenue',id)} openSchedule={openSchedule} act={act} compact/></>;
 return <><div className="admin-hero"><div><span>ADMINISTRATION CENTER</span><h2>Chào mừng trở lại, quản trị viên.</h2><p>Đây là bức tranh tổng quan về hoạt động của Sân Nhà Mình.</p></div><div className="admin-hero-mark"><ShieldCheck size={48}/></div></div><div className="stats-grid admin-stats"><StatCard label="Tổng tài khoản" value={stats.accounts||0} Icon={Users} sub="Thành viên đang lưu trữ"/><StatCard label="Sân hoạt động" value={stats.venues||0} Icon={Building2} sub={`${stats.pendingVenues||0} sân chờ duyệt`}/><StatCard label="Đặt sân chờ xử lý" value={stats.pendingBookings||0} Icon={CalendarDays}/><StatCard label="Thanh toán chờ duyệt" value={stats.pendingPayments||0} Icon={CreditCard}/><StatCard label="Tổng giao dịch thành công" value={money(stats.revenue)} Icon={DollarSign}/></div><div className="two-col"><div className="panel"><SectionHead title="Yêu cầu sân cần duyệt" action="Quản lý sân" onAction={()=>setPage('venues')}/><div className="compact-list">{venues.filter(v=>v.status==='PENDING').slice(0,4).map(v=><div className="compact-row" key={v.id}><div className="list-avatar"><Building2 size={17}/></div><div className="compact-main"><b>{v.name}</b><small>{v.owner_name} · {v.district||v.city}</small></div><div className="inline-actions"><button className="mini-btn green" onClick={()=>act('patch',`/admin/venues/${v.id}/status`,{status:'ACTIVE'})}><Check size={15}/></button><button className="mini-btn red" onClick={()=>act('patch',`/admin/venues/${v.id}/status`,{status:'REJECTED'})}><X size={15}/></button></div></div>)}{!venues.some(v=>v.status==='PENDING')&&<Empty text="Không có sân chờ duyệt"/>}</div></div><div className="panel"><SectionHead title="Đặt sân gần đây" action="Xem tất cả" onAction={()=>setPage('bookings')}/><div className="compact-list">{rows.slice(0,5).map(b=><div className="compact-row" key={b.id}><div className="list-avatar"><CalendarDays size={17}/></div><div className="compact-main"><b>{b.venue_name}</b><small>{b.player_name} · {dateText(b.play_date)}</small></div><Status value={b.status}/></div>)}</div></div></div></>
}
function SectionHead({title,action,onAction}){return <div className="section-head"><h3>{title}</h3>{action&&<button onClick={onAction}>{action}<ArrowRight size={14}/></button>}</div>}
function Status({value}){return <span className={`status status-${String(value||'').toLowerCase()}`}>{statusText[value]||value||'—'}</span>}
function Empty({text,action,onClick}){return <div className="empty-state"><div className="empty-icon"><ClipboardList size={24}/></div><b>{text}</b>{action&&<button className="btn btn-primary btn-small" onClick={onClick}>{action}</button>}</div>}
function VenueGrid({venues,book,favoriteIds,onToggleFavorite}){return <div className="venue-grid">{venues.map(v=>{const liked=favoriteIds?.has(v.id);return <article className="venue-card" key={v.id}><div className="venue-photo" style={{backgroundImage:`url(${v.image_url||`https://images.unsplash.com/photo-1522778119026-d647f0596c20?w=900`})`}}><span className="photo-tag">{v.category_name||'Sân thể thao'}</span><div className="photo-right">{onToggleFavorite&&<button type="button" className={`fav-btn ${liked?'liked':''}`} title={liked?'Bỏ yêu thích':'Lưu yêu thích'} aria-label={liked?'Bỏ yêu thích':'Lưu yêu thích'} onClick={()=>onToggleFavorite(v)}><Heart size={13} fill={liked?'currentColor':'none'}/></button>}<span className="rating"><Star size={13} fill="currentColor"/> {Number(v.rating||0).toFixed(1)}</span></div></div><div className="venue-body"><h3>{v.name}</h3><p><MapPin size={14}/>{v.address||v.district||v.city}</p><div className="venue-card-bottom"><div><b>{money(v.price_per_hour)}</b><small>/ giờ</small></div>{book&&<button className="btn btn-primary btn-small" onClick={()=>book(v)}>Đặt sân <ArrowRight size={14}/></button>}</div></div></article>})}</div>}
function VenueExplorer({venues,search,setSearch,categories,category='',setCategory=()=>{},pageInfo={totalPages:0,totalElements:venues.length},page=0,setPage=()=>{},openBooking,favoriteIds,onToggleFavorite}){return <><div className="search-panel"><div className="search-field"><Search size={18}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Tìm theo tên sân, địa chỉ, khu vực..."/></div><div className="select-field"><Filter size={16}/><select value={category} onChange={e=>{setCategory(e.target.value);setPage(0)}}><option value="">Tất cả bộ môn</option>{categories.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></div></div><div className="results-meta"><b>{pageInfo.totalElements||0} sân thể thao</b><span>Trang {pageInfo.totalPages? page+1:0}/{pageInfo.totalPages||0}</span></div><VenueGrid venues={venues} book={openBooking} favoriteIds={favoriteIds} onToggleFavorite={onToggleFavorite}/>{venues.length===0&&<Empty text="Chưa tìm thấy sân phù hợp. Hãy thử từ khóa khác."/>}{pageInfo.totalPages>1&&<div className="pagination"><button className="btn btn-light" disabled={page===0} onClick={()=>setPage(p=>Math.max(0,p-1))}>Trang trước</button><span>Trang {page+1} / {pageInfo.totalPages}</span><button className="btn btn-light" disabled={page+1>=pageInfo.totalPages} onClick={()=>setPage(p=>p+1)}>Trang sau</button></div>}</>}
function DataTable({columns,rows,empty='Chưa có dữ liệu',searchable=true,filters=null}){const [q,setQ]=useState('');const filtered=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase()));return <div className="table-panel">{searchable&&<div className="table-toolbar"><div className="table-toolbar-left"><div className="table-search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Tìm kiếm trong danh sách..."/></div>{filters}</div><span>{filtered.length} kết quả</span></div>}<div className="table-wrap"><table><thead><tr>{columns.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{filtered.map((r,i)=><tr key={r.id||i}>{columns.map(c=><td key={c.key}>{c.render?c.render(r):r[c.key]??'—'}</td>)}</tr>)}</tbody></table>{filtered.length===0&&<Empty text={empty}/>}</div></div>}

function OwnerVenues({rows,categories=[],openForm,openDetail,openSchedule,act,compact=false}){
 const [catFilter,setCatFilter]=useState('');
 const [statusFilter,setStatusFilter]=useState('');
 const visibleRows=compact?rows:rows.filter(r=>(!catFilter||String(r.category_id)===String(catFilter))&&(!statusFilter||r.status===statusFilter));
 const filters=compact?null:<><select className="table-filter" value={catFilter} onChange={e=>setCatFilter(e.target.value)}><option value="">Tất cả bộ môn</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select className="table-filter" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">Tất cả trạng thái</option><option value="ACTIVE">Đang hoạt động</option><option value="PENDING">Chờ duyệt</option><option value="REJECTED">Bị từ chối</option></select></>;
 return <DataTable searchable={!compact} filters={filters} rows={visibleRows} columns={[{key:'name',label:'Tên sân',render:r=><div className="table-title"><div className="list-avatar"><Building2 size={17}/></div><div><b>{r.name}</b><small>{r.address}</small></div></div>},{key:'price_per_hour',label:'Giá / giờ',render:r=>money(r.price_per_hour)},{key:'category_name',label:'Bộ môn'},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Thao tác',render:r=><div className="inline-actions">{openDetail&&<button type="button" className="mini-btn" title="Xem chi tiết" onClick={()=>openDetail(r.id)}><Eye size={15}/></button>}{openForm&&<button type="button" className="mini-btn" title="Chỉnh sửa" onClick={()=>openForm('venue',r)}><Pencil size={15}/></button>}{openSchedule&&<button type="button" className="mini-btn" title="Lịch hoạt động" onClick={()=>openSchedule(r)}><Clock size={15}/></button>}{act&&<button type="button" className="mini-btn red" title="Xóa / Lưu trữ" onClick={()=>confirm('Xóa (lưu trữ) sân bóng này?')&&act('delete',`/owner/venues/${r.id}`,undefined,'Đã xóa (lưu trữ) sân bóng')}><Trash2 size={15}/></button>}</div>}]}/>;
}

function ScheduleModal({value,onClose,onSave}){const [rows,setRows]=useState(value.rows);const days=['Thứ hai','Thứ ba','Thứ tư','Thứ năm','Thứ sáu','Thứ bảy','Chủ nhật'];const update=(i,k,v)=>setRows(old=>old.map((r,n)=>n===i?{...r,[k]:v}:r));return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal-card schedule-card"><div className="modal-head"><div><span className="eyebrow">CẤU HÌNH SÂN</span><h2>Lịch hoạt động · {value.venue.name}</h2></div><button className="icon-btn" onClick={onClose}><X/></button></div><div className="schedule-list">{rows.map((r,i)=><div className={`schedule-row ${r.isClosed?'closed':''}`} key={i}><b>{days[i]}</b><label className="schedule-toggle"><input type="checkbox" checked={!r.isClosed} onChange={e=>update(i,'isClosed',!e.target.checked)}/> Mở cửa</label><input aria-label="Giờ mở cửa" type="time" value={r.openTime} disabled={r.isClosed} onChange={e=>update(i,'openTime',e.target.value)}/><span>đến</span><input aria-label="Giờ đóng cửa" type="time" value={r.closeTime} disabled={r.isClosed} onChange={e=>update(i,'closeTime',e.target.value)}/><select value={r.slotMinutes} disabled={r.isClosed} onChange={e=>update(i,'slotMinutes',Number(e.target.value))}><option value="30">30 phút</option><option value="60">60 phút</option><option value="120">120 phút</option></select></div>)}</div><div className="modal-footer"><button className="btn btn-light" onClick={onClose}>Đóng</button><button className="btn btn-primary" onClick={()=>onSave(rows)}>Lưu lịch hoạt động <Check size={16}/></button></div></div></div>}

function AdminVenues({rows,categories=[],act,openForm,openDetail}){
 const [catFilter,setCatFilter]=useState('');
 const [statusFilter,setStatusFilter]=useState('');
 const visibleRows=rows.filter(r=>(!catFilter||String(r.category_id)===String(catFilter))&&(!statusFilter||r.status===statusFilter));
 const filters=<><select className="table-filter" value={catFilter} onChange={e=>setCatFilter(e.target.value)}><option value="">Tất cả bộ môn</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select className="table-filter" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">Tất cả trạng thái</option><option value="ACTIVE">Đang hoạt động</option><option value="PENDING">Chờ duyệt</option><option value="REJECTED">Bị từ chối</option><option value="ARCHIVED">Đã lưu trữ</option></select></>;
 return <DataTable filters={filters} rows={visibleRows} columns={[{key:'name',label:'Sân bóng / thể thao',render:r=><div className="table-title"><div className="list-avatar"><Building2 size={17}/></div><div><b>{r.name}</b><small>{r.address}{r.district?`, ${r.district}`:''}</small></div></div>},{key:'category_name',label:'Bộ môn'},{key:'owner_name',label:'Chủ sân'},{key:'price_per_hour',label:'Giá / giờ',render:r=>money(r.price_per_hour)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Thao tác',render:r=><div className="inline-actions"><button type="button" className="mini-btn" title="Xem chi tiết" onClick={()=>openDetail(r.id)}><Eye size={15}/></button><button type="button" className="mini-btn" title="Chỉnh sửa" onClick={()=>openForm('adminVenue',r)}><Pencil size={15}/></button>{r.status==='PENDING'&&<><button type="button" className="mini-btn green" title="Duyệt" onClick={()=>act('patch',`/admin/venues/${r.id}/status`,{status:'ACTIVE'},'Đã duyệt sân bóng')}><Check size={15}/></button><button type="button" className="mini-btn red" title="Từ chối" onClick={()=>act('patch',`/admin/venues/${r.id}/status`,{status:'REJECTED'},'Đã từ chối duyệt sân')}><X size={15}/></button></>}{r.status!=='ARCHIVED'&&<button type="button" className="mini-btn red" title="Xóa / Lưu trữ" onClick={()=>confirm('Xóa (lưu trữ) sân bóng này?')&&act('delete',`/admin/venues/${r.id}`,undefined,'Đã xóa (lưu trữ) sân bóng')}><Trash2 size={15}/></button>}{(r.status==='ARCHIVED'||r.status==='REJECTED')&&<button type="button" className="mini-btn green" title="Khôi phục hoạt động" onClick={()=>act('patch',`/admin/venues/${r.id}/status`,{status:'ACTIVE'},'Đã khôi phục sân bóng')}><RefreshCw size={15}/></button>}</div>}]}/>;
}

function PlayerBookings({rows,act,openForm}){return <DataTable rows={rows} columns={[{key:'booking_code',label:'Mã đặt sân'},{key:'venue_name',label:'Địa điểm',render:r=><div><b>{r.venue_name}</b><small className="subline">{r.address}</small></div>},{key:'play_date',label:'Ngày chơi',render:r=>dateText(r.play_date)},{key:'start_time',label:'Khung giờ',render:r=>`${String(r.start_time||'').slice(0,5)} – ${String(r.end_time||'').slice(0,5)}`},{key:'total_amount',label:'Chi phí',render:r=>money(r.total_amount)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Thao tác',render:r=><div className="inline-actions">{r.status==='CONFIRMED'&&<button className="mini-btn" title="Thanh toán" onClick={()=>openForm('payment',{bookingId:r.id,bookingCode:r.booking_code,amount:r.total_amount})}><CreditCard size={15}/></button>}{['PENDING_OWNER','CONFIRMED'].includes(r.status)&&<button className="mini-btn red" title="Hủy lịch" onClick={()=>confirm('Bạn chắc chắn muốn hủy lịch?')&&act('patch',`/bookings/${r.id}/cancel`,{})}><X size={15}/></button>}{r.status==='COMPLETED'&&<button className="mini-btn" title="Đánh giá" onClick={()=>openForm('review',{bookingId:r.id})}><Star size={15}/></button>}</div>}]}/>}
function OwnerBookings({rows,act,saving=false}){return <DataTable rows={rows} columns={[{key:'booking_code',label:'Mã đặt sân'},{key:'player_name',label:'Khách hàng',render:r=><div><b>{r.player_name}</b><small className="subline">{r.player_phone}</small></div>},{key:'venue_name',label:'Sân'},{key:'play_date',label:'Ngày chơi',render:r=>dateText(r.play_date)},{key:'start_time',label:'Khung giờ',render:r=>`${String(r.start_time||'').slice(0,5)} – ${String(r.end_time||'').slice(0,5)}`},{key:'total_amount',label:'Giá trị',render:r=>money(r.total_amount)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Xử lý',render:r=>{const st=String(r.status||'').trim().toUpperCase();return <div className="inline-actions">{st==='PENDING_OWNER'&&<><button type="button" className="mini-btn green" title="Xác nhận" disabled={saving} onClick={()=>act('patch',`/owner/bookings/${r.id}/decision`,{accept:true},'Đã xác nhận lịch đặt sân')}><Check size={15}/></button><button type="button" className="mini-btn red" title="Từ chối" disabled={saving} onClick={()=>act('patch',`/owner/bookings/${r.id}/decision`,{accept:false},'Đã từ chối lịch đặt sân')}><X size={15}/></button></>}{st==='CONFIRMED'&&<button type="button" className="mini-btn green" title="Hoàn thành" disabled={saving} onClick={()=>act('patch',`/owner/bookings/${r.id}/complete`,{},'Đã đánh dấu hoàn thành lịch đặt')}><CheckCircle2 size={15}/></button>}</div>}}]}/>}
function AdminBookings({rows,act}){return <DataTable rows={rows} columns={[{key:'booking_code',label:'Mã đặt sân'},{key:'venue_name',label:'Sân'},{key:'player_name',label:'Khách hàng'},{key:'owner_name',label:'Chủ sân'},{key:'play_date',label:'Ngày chơi',render:r=>dateText(r.play_date)},{key:'total_amount',label:'Giá trị',render:r=>money(r.total_amount)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Thao tác',render:r=><button className="mini-btn red" disabled={!['PENDING_OWNER','CONFIRMED'].includes(r.status)} onClick={()=>confirm('Admin hủy lịch đặt này?')&&act('patch',`/admin/bookings/${r.id}/cancel`,{})}><Ban size={15}/></button>}]}/>}
function PlayerPayments({rows}){return <DataTable rows={rows} columns={[{key:'booking_code',label:'Mã đặt sân'},{key:'venue_name',label:'Địa điểm'},{key:'method',label:'Phương thức',render:r=>methodLabel(r.method)},{key:'amount',label:'Số tiền',render:r=>money(r.amount)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'created_at',label:'Ngày tạo',render:r=>r.created_at?new Date(r.created_at).toLocaleString('vi-VN'):'—'}]}/>}
function methodLabel(m){return ({BANK_TRANSFER:'Chuyển khoản',CASH:'Tiền mặt',VNPAY:'VNPay',MOMO:'MoMo'})[m]||m}
function AdminPayments({rows,act}){return <DataTable rows={rows} columns={[{key:'booking_code',label:'Mã đặt sân'},{key:'payer_name',label:'Người thanh toán'},{key:'venue_name',label:'Địa điểm'},{key:'method',label:'Phương thức',render:r=>methodLabel(r.method)},{key:'amount',label:'Số tiền',render:r=>money(r.amount)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Xử lý',render:r=><div className="inline-actions">{r.status==='PENDING'&&<button className="mini-btn green" title="Xác nhận đã nhận tiền" onClick={()=>act('patch',`/admin/payments/${r.id}/confirm`,{note:'Đã kiểm tra giao dịch thủ công'})}><Check size={15}/></button>}{r.status==='REFUND_PENDING'&&<button className="mini-btn green" title="Xác nhận đã hoàn tiền ngoài hệ thống" onClick={()=>confirm('Xác nhận tiền đã được hoàn thực tế?')&&act('patch',`/admin/payments/${r.id}/refund`,{note:'Đã hoàn tiền ngoài hệ thống'})}><RefreshCw size={15}/></button>}</div>}]}/>}

function AdminAccounts({rows,openForm,openDetail,act}){
 const [roleFilter,setRoleFilter]=useState('');
 const [statusFilter,setStatusFilter]=useState('');
 const visibleRows=rows.filter(r=>(!roleFilter||r.role===roleFilter)&&(!statusFilter||r.status===statusFilter));
 const filters=<><select className="table-filter" value={roleFilter} onChange={e=>setRoleFilter(e.target.value)}><option value="">Tất cả vai trò</option><option value="PLAYER">Khách hàng</option><option value="OWNER">Chủ sân</option><option value="ADMIN">Quản trị viên</option></select><select className="table-filter" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">Tất cả trạng thái</option><option value="ACTIVE">Đang hoạt động</option><option value="LOCKED">Đã khóa</option><option value="DELETED">Đã vô hiệu hóa</option></select></>;
 return <DataTable filters={filters} rows={visibleRows} columns={[{key:'full_name',label:'Người dùng',render:r=><div className="table-title"><div className="avatar small-avatar">{r.full_name?.[0]}</div><div><b>{r.full_name}</b><small>{r.email}</small></div></div>},{key:'phone',label:'Điện thoại'},{key:'role',label:'Vai trò',render:r=><span className="role-pill">{roleLabel(r.role)}</span>},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'created_at',label:'Ngày tham gia',render:r=>dateText(r.created_at)},{key:'actions',label:'Thao tác',render:r=><div className="inline-actions"><button type="button" className="mini-btn" title="Xem chi tiết" onClick={()=>openDetail(r.id)}><Eye size={15}/></button><button type="button" className="mini-btn" title="Chỉnh sửa" onClick={()=>openForm('account',r)}><Pencil size={15}/></button>{r.status==='ACTIVE'?<button type="button" className="mini-btn red" title="Khóa tài khoản" onClick={()=>act('patch',`/admin/accounts/${r.id}/status`,{status:'LOCKED'},'Đã khóa tài khoản')}><Ban size={15}/></button>:r.status==='LOCKED'?<button type="button" className="mini-btn green" title="Mở khóa" onClick={()=>act('patch',`/admin/accounts/${r.id}/status`,{status:'ACTIVE'},'Đã mở khóa tài khoản')}><Check size={15}/></button>:<button type="button" className="mini-btn green" title="Khôi phục tài khoản" onClick={()=>act('patch',`/admin/accounts/${r.id}/status`,{status:'ACTIVE'},'Đã khôi phục tài khoản')}><RefreshCw size={15}/></button>}{r.status!=='DELETED'&&<button type="button" className="mini-btn red" title="Xóa / Vô hiệu hóa" onClick={()=>confirm('Xóa (vô hiệu hóa) người dùng này?')&&act('delete',`/admin/accounts/${r.id}`,undefined,'Đã xóa (vô hiệu hóa) người dùng')}><Trash2 size={15}/></button>}<button type="button" className="mini-btn" title="Đặt lại mật khẩu" onClick={()=>openForm('resetPassword',r)}><KeyRound size={15}/></button></div>}]}/>;
}

function OwnerReviews({rows,act}){return <DataTable rows={rows} columns={[{key:'player_name',label:'Khách hàng'},{key:'venue_name',label:'Sân'},{key:'rating',label:'Đánh giá',render:r=><span className="stars"><Star size={14} fill="currentColor"/>{r.rating}/5</span>},{key:'content',label:'Nội dung'},{key:'owner_reply',label:'Phản hồi',render:r=>r.owner_reply||<span className="muted">Chưa phản hồi</span>},{key:'actions',label:'Thao tác',render:r=><button className="mini-btn" title="Phản hồi" onClick={()=>{const reply=prompt('Nhập nội dung phản hồi:',r.owner_reply||'');if(reply!==null)act('patch',`/owner/reviews/${r.id}/reply`,{reply})}}><MessageSquare size={15}/></button>}]}/> }
function AdminReviews({rows,act}){return <DataTable rows={rows} columns={[{key:'player_name',label:'Người đánh giá'},{key:'venue_name',label:'Sân'},{key:'rating',label:'Điểm',render:r=><span className="stars"><Star size={14} fill="currentColor"/>{r.rating}/5</span>},{key:'content',label:'Nội dung'},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>},{key:'actions',label:'Kiểm duyệt',render:r=><button className={`mini-btn ${r.status==='VISIBLE'?'red':'green'}`} onClick={()=>act('patch',`/admin/reviews/${r.id}/visibility`,{visible:r.status!=='VISIBLE'})}>{r.status==='VISIBLE'?<Eye size={15}/>:<Check size={15}/>}</button>}]}/>}
function Categories({rows,openForm,act}){return <DataTable rows={rows} columns={[{key:'name',label:'Tên danh mục'},{key:'description',label:'Mô tả'},{key:'active',label:'Trạng thái',render:r=><Status value={r.active?'ACTIVE':'ARCHIVED'}/>},{key:'actions',label:'Thao tác',render:r=><div className="inline-actions"><button className="mini-btn" onClick={()=>openForm('category',r)}><Pencil size={15}/></button><button className="mini-btn red" onClick={()=>act('delete',`/admin/categories/${r.id}`)}><Trash2 size={15}/></button></div>}]}/>}
function Notifications({rows,act}){return <div className="notification-list">{rows.map(n=><div className={`notification-card ${n.is_read?'read':''}`} key={n.id}><div className="notification-icon"><Bell size={18}/></div><div className="notification-copy"><b>{n.title}</b><p>{n.message}</p><small>{n.created_at?new Date(n.created_at).toLocaleString('vi-VN'):''}</small></div>{!n.is_read&&<button className="btn btn-light btn-small" onClick={()=>act('patch',`/notifications/${n.id}/read`,{})}>Đánh dấu đã đọc</button>}</div>)}{!rows.length&&<Empty text="Bạn chưa có thông báo nào."/>}</div>}
function Audit({rows}){return <DataTable rows={rows} columns={[{key:'created_at',label:'Thời gian',render:r=>r.created_at?new Date(r.created_at).toLocaleString('vi-VN'):'—'},{key:'actor_name',label:'Người thực hiện'},{key:'action',label:'Hành động'},{key:'target_type',label:'Đối tượng'},{key:'target_id',label:'ID'},{key:'details',label:'Chi tiết'}]}/>}
function Revenue({rows,stats}){return <><div className="stats-grid"><StatCard label="Doanh thu tháng" value={money(stats.monthRevenue)} Icon={Wallet}/><StatCard label="Giao dịch đã thanh toán" value={rows.length} Icon={CalendarDays}/><StatCard label="Tổng doanh thu ghi nhận" value={money(rows.reduce((s,x)=>s+Number(x.amount||0),0))} Icon={Activity}/></div><div className="panel"><SectionHead title="Giao dịch thanh toán đã xác nhận"/><DataTable searchable={false} rows={rows} columns={[{key:'booking_code',label:'Mã đặt sân'},{key:'venue_name',label:'Sân'},{key:'payer_name',label:'Khách hàng'},{key:'amount',label:'Doanh thu',render:r=>money(r.amount)},{key:'method',label:'Phương thức',render:r=>methodLabel(r.method)},{key:'status',label:'Trạng thái',render:r=><Status value={r.status}/>}]}/></div></>}

function DetailModal({detail,onClose,onEdit}){
 const {kind,data}=detail;
 if(kind==='account'){
   return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal-card"><div className="modal-head"><div><span className="eyebrow">CHI TIẾT NGƯỜI DÙNG</span><h2>{data.full_name}</h2></div><button type="button" className="icon-btn" onClick={onClose}><X/></button></div><div className="detail-grid"><div><small>ID</small><b>#{data.id}</b></div><div><small>Vai trò</small><span className="role-pill">{roleLabel(data.role)}</span></div><div><small>Email</small><b>{data.email}</b></div><div><small>Số điện thoại</small><b>{data.phone||'Chưa cập nhật'}</b></div><div><small>Trạng thái</small><Status value={data.status}/></div><div><small>Ngày tham gia</small><b>{dateText(data.created_at)}</b></div><div><small>Số sân đang quản lý</small><b>{data.venue_count??0}</b></div><div><small>Số lịch đã đặt</small><b>{data.booking_count??0}</b></div></div><div className="modal-footer"><button type="button" className="btn btn-light" onClick={onClose}>Đóng</button><button type="button" className="btn btn-primary" onClick={onEdit}><Pencil size={15}/> Chỉnh sửa</button></div></div></div>;
 }
 return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal-card"><div className="modal-head"><div><span className="eyebrow">CHI TIẾT SÂN BÓNG</span><h2>{data.name}</h2></div><button type="button" className="icon-btn" onClick={onClose}><X/></button></div>{data.image_url&&<div className="detail-banner" style={{backgroundImage:`url(${data.image_url})`}}/>}<div className="detail-grid"><div><small>Bộ môn</small><b>{data.category_name||'Chưa phân loại'}</b></div><div><small>Trạng thái</small><Status value={data.status}/></div><div><small>Giá thuê / giờ</small><b>{money(data.price_per_hour)}</b></div><div><small>Đánh giá</small><b>{Number(data.rating||0).toFixed(1)} / 5</b></div>{data.owner_name&&<div><small>Chủ sân</small><b>{data.owner_name}{data.owner_phone?` · ${data.owner_phone}`:''}</b></div>}<div><small>Địa chỉ</small><b>{[data.address,data.district,data.city].filter(Boolean).join(', ')}</b></div><div className="span-2"><small>Mô tả</small><p className="detail-text">{data.description||'Chưa có mô tả chi tiết.'}</p></div>{Array.isArray(data.schedules)&&data.schedules.length>0&&<div className="span-2"><small>Lịch hoạt động</small><div className="detail-schedules">{data.schedules.map(sc=><span key={sc.day_of_week} className={`schedule-pill ${sc.is_closed?'closed':''}`}>{dayLabels[sc.day_of_week]||sc.day_of_week}: {sc.is_closed?'Nghỉ':`${String(sc.open_time).slice(0,5)}–${String(sc.close_time).slice(0,5)}`}</span>)}</div></div>}</div><div className="modal-footer"><button type="button" className="btn btn-light" onClick={onClose}>Đóng</button><button type="button" className="btn btn-primary" onClick={onEdit}><Pencil size={15}/> Chỉnh sửa</button></div></div></div>;
}

function Modal({modal,setModal,setField,submit,busy,categories,owners=[]}){
 const f=modal.form||{};
 const alwaysRequired=new Set(['name','fullName','email','address','pricePerHour','ownerId','playDate','startTime','hours','title']);
 const field=(name,label,type='text',placeholder='',extra={})=><label>{label}<input type={type} value={f[name]??''} placeholder={placeholder} onChange={e=>setField(name,e.target.value)} required={alwaysRequired.has(name)||(name==='password'&&(!modal.item||modal.kind==='resetPassword'))} {...extra}/></label>;
 const select=(name,label,opts,emptyLabel='Chưa có dữ liệu')=><label>{label}<select required={name==='categoryId'||name==='ownerId'} value={f[name]??opts[0]?.[0]??''} onChange={e=>setField(name,e.target.value)}>{opts.length===0?<option value="">{emptyLabel}</option>:opts.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select></label>;
 const area=(name,label,required=false)=><label className="span-2">{label}<textarea rows="3" required={required} value={f[name]??''} onChange={e=>setField(name,e.target.value)}/></label>;
 let title='',fields=null;
 switch(modal.kind){
 case 'venue':case 'adminVenue':title=modal.item?'Chỉnh sửa sân bóng':'Thêm sân bóng mới';fields=<>{modal.kind==='adminVenue'&&(owners.length>0?select('ownerId','Chủ sân',owners.map(o=>[o.id,`${o.full_name} (${o.email})`]),'Chưa có tài khoản chủ sân'):field('ownerId','ID tài khoản chủ sân','number','',{min:1}))}{field('name','Tên sân bóng')}{select('categoryId','Bộ môn',categories.map(c=>[c.id,c.name]),'Chưa có dữ liệu danh mục')}{field('address','Địa chỉ')}{field('district','Quận / huyện')}{field('city','Tỉnh / thành phố')}{field('pricePerHour','Giá thuê mỗi giờ (VND)','number','',{min:1})}{field('imageUrl','Đường dẫn ảnh')}{modal.kind==='adminVenue'&&modal.item&&select('status','Trạng thái',[['ACTIVE','Đang hoạt động'],['PENDING','Chờ duyệt'],['REJECTED','Bị từ chối'],['ARCHIVED','Đã lưu trữ']])}{area('description','Mô tả sân')}</>;break;
 case 'account':title=modal.item?'Chỉnh sửa người dùng':'Thêm người dùng mới';fields=<>{field('fullName','Họ và tên')}{field('email','Email','email')}{field('phone','Số điện thoại')}{select('role','Vai trò',[['PLAYER','Khách hàng'],['OWNER','Chủ sân'],['ADMIN','Quản trị viên']])}{modal.item?select('status','Trạng thái',[['ACTIVE','Đang hoạt động'],['LOCKED','Đã khóa'],['DELETED','Đã vô hiệu hóa']]):field('password','Mật khẩu tạm','password','',{minLength:8,maxLength:72})}</>;break;
 case 'resetPassword':title='Đặt lại mật khẩu';fields=<><div className="modal-note span-2">Tài khoản: <b>{f.fullName}</b> ({f.email})</div><label className="span-2">Mật khẩu mới (8–72 ký tự)<input type="password" required minLength={8} maxLength={72} value={f.password??''} onChange={e=>setField('password',e.target.value)} placeholder="Nhập mật khẩu mới"/></label></>;break;
 case 'category':title=modal.item?'Sửa danh mục':'Thêm danh mục';fields=<>{field('name','Tên danh mục')}{area('description','Mô tả')}</>;break;
 case 'booking':title=`Đặt sân: ${f.venueName||''}`;fields=<>{field('playDate','Ngày chơi','date','',{min:localToday()})}{field('startTime','Giờ bắt đầu','time')}{field('hours','Thời lượng (1–4 giờ)','number','',{min:1,max:4})}{area('note','Ghi chú cho chủ sân')}</>;break;
 case 'payment':title='Gửi thông tin thanh toán';fields=<><div className="modal-note span-2">Mã đặt sân: <b>{f.bookingCode}</b> · Số tiền: <b>{money(f.amount)}</b></div>{select('method','Phương thức thanh toán',[['BANK_TRANSFER','Chuyển khoản ngân hàng'],['CASH','Tiền mặt tại sân'],['VNPAY','VNPay (chưa kích hoạt)'],['MOMO','MoMo (chưa kích hoạt)']])}{field('transactionRef','Mã giao dịch / nội dung chuyển khoản')}</>;break;
 case 'review':title='Đánh giá trải nghiệm';fields=<>{select('rating','Mức đánh giá',[[5,'5 - Tuyệt vời'],[4,'4 - Tốt'],[3,'3 - Bình thường'],[2,'2 - Chưa tốt'],[1,'1 - Không hài lòng']])}{area('content','Chia sẻ cảm nhận')}</>;break;
 case 'broadcast':title='Gửi thông báo hệ thống';fields=<>{select('target','Đối tượng nhận',[['ALL','Tất cả thành viên'],['PLAYER','Khách hàng'],['OWNER','Chủ sân']])}{field('title','Tiêu đề')}{area('message','Nội dung thông báo',true)}</>;break;
 default:return null;
 }
 return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setModal(null)}><form className="modal-card" onSubmit={submit}><div className="modal-head"><div><span className="eyebrow">SÂN NHÀ MÌNH</span><h2>{title}</h2></div><button type="button" className="icon-btn" onClick={()=>setModal(null)}><X/></button></div><div className="modal-grid">{fields}</div>{(modal.kind==='venue'||modal.kind==='adminVenue')&&categories.length===0&&<p className="modal-note">Chưa tải được danh mục sân. Hãy kiểm tra kết nối database và bảng categories trước khi lưu.</p>}<div className="modal-footer"><button type="button" className="btn btn-light" onClick={()=>setModal(null)}>Hủy</button><button className="btn btn-primary" disabled={busy||((modal.kind==='venue'||modal.kind==='adminVenue')&&categories.length===0)}>{busy?'Đang lưu...':'Lưu thông tin'} <Check size={16}/></button></div></form></div>
}
export default App;
